"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6712],{33868:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"WorkbenchGuiController","desc":"Drives the Studio-authored `WorkbenchGui`. Opens via a placed Workbench\\nstation\'s `CraftPromptPart` ProximityPrompt (CollectionService tag `Workbench`,\\nshared with the Shredder on the same station Model). Two pages under a\\n`UIPageLayout`, switched by the `Personal` (workbench) and `Recharge`\\n(armory) tab buttons:\\n\\n- **Workbench** \u2014 builds the recipe grid from `WorkbenchConfig`, fills the\\n  detail pane on selection, sends `ReqCraft` on Accept. Greys recipes the\\n  player can\'t afford or that are gated by a locked Tech node. The grid is\\n  filtered by category; the `DropdownButton` (driven by the reusable\\n  `SharedModules/Gui/Dropdown` widget) fires `Signals.RequestWorkbenchCategory`.\\n- **Armory** \u2014 lists owned armor from `ArmorClient`, shows the selected\\n  kind\'s stats, equips it, and recharges an Energy kind while the charge\\n  button is held for `ArmorConfig.RECHARGE_HOLD_TIME`.\\n\\nBoth pages repaint live on MaterialPool, armor and Tech-unlock changes. Each\\npage repeats Stash/Move, wired via `PlaceableActions`. The `CloseButton`\\ncalls `close()`. `ResponsiveScale` shrinks text-size limits and scrollbar\\nthickness on screens smaller than the 1080p the GUI was authored at.","realm":["Client"],"source":{"line":26,"path":"src/StarterPlayer/StarterPlayerScripts/WorkbenchGuiController.client.luau"}}')}}]);